/**
 * File: p2p-kids-marketplace/src/hooks/useItemDraft.ts
 * MODULE-04 LISTING-V3-004: Item Draft Hook
 * 
 * Provides autosave functionality for item drafts with:
 * - 30-second interval auto-save
 * - AppState background flush
 * - Navigation blur flush
 * - Immediate save method
 * - Error state management
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { AppState, AppStateStatus } from 'react-native';
import { useNavigation, useFocusEffect } from '@react-navigation/native';
import { ItemDraft, DraftData } from '../types/listing';
import {
  createItemDraft,
  getItemDraft,
  updateItemDraft,
  deleteItemDraft,
} from '../services/draftService';

const AUTOSAVE_INTERVAL_MS = 30000; // 30 seconds

export interface UseItemDraftResult {
  draft: ItemDraft | null;
  save: (updates: Partial<DraftData>) => void;
  saveNow: () => Promise<void>;
  discard: () => Promise<void>;
  isSaving: boolean;
  saveError: string | null;
  isLoading: boolean;
}

/**
 * Hook for managing item draft with autosave
 * 
 * Features:
 * - Loads existing draft on mount if draftId provided
 * - Auto-saves every 30s while screen is focused
 * - Flushes pending changes on AppState -> background
 * - Flushes pending changes on navigation blur
 * - Provides immediate save method
 * - Never throws - exposes saveError instead
 * 
 * @param draftId - Optional existing draft ID to load
 * @param sellerId - Seller ID for creating new draft
 * @returns Draft state and control methods
 */
export function useItemDraft(
  draftId?: string,
  sellerId?: string
): UseItemDraftResult {
  const [draft, setDraft] = useState<ItemDraft | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const navigation = useNavigation();
  const autosaveTimerRef = useRef<NodeJS.Timeout | null>(null);
  const pendingUpdatesRef = useRef<Partial<DraftData> | null>(null);
  const appStateRef = useRef(AppState.currentState);

  // Load existing draft on mount
  useEffect(() => {
    if (draftId) {
      loadDraft(draftId);
    } else if (sellerId) {
      createNewDraft(sellerId);
    } else {
      setIsLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draftId, sellerId]);

  // Load draft from server
  const loadDraft = async (id: string) => {
    try {
      setIsLoading(true);
      const loaded = await getItemDraft(id);
      if (loaded) {
        setDraft(loaded);
      } else {
        setSaveError('Draft not found or expired');
      }
    } catch (error: any) {
      setSaveError(error.message || 'Failed to load draft');
    } finally {
      setIsLoading(false);
    }
  };

  // Create new draft
  const createNewDraft = async (seller_id: string) => {
    try {
      setIsLoading(true);
      const created = await createItemDraft(seller_id);
      if (created) {
        setDraft(created);
      } else {
        setSaveError('Failed to create draft');
      }
    } catch (error: any) {
      setSaveError(error.message || 'Failed to create draft');
    } finally {
      setIsLoading(false);
    }
  };

  // Queue updates for autosave
  const save = useCallback((updates: Partial<DraftData>) => {
    setSaveError(null);

    // Merge with pending updates
    if (pendingUpdatesRef.current) {
      pendingUpdatesRef.current = { ...pendingUpdatesRef.current, ...updates };
    } else {
      pendingUpdatesRef.current = updates;
    }

    // Update local draft state immediately for UI responsiveness
    setDraft((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        draft_data: { ...prev.draft_data, ...updates },
        updated_at: new Date().toISOString(),
      };
    });
  }, []);

  // Flush pending updates immediately
  const saveNow = useCallback(async () => {
    if (!draft || !pendingUpdatesRef.current) return;

    try {
      setIsSaving(true);
      setSaveError(null);

      const success = await updateItemDraft(draft.id, pendingUpdatesRef.current);

      if (success) {
        pendingUpdatesRef.current = null;
      } else {
        setSaveError('Failed to save draft');
      }
    } catch (error: any) {
      setSaveError(error.message || 'Failed to save draft');
    } finally {
      setIsSaving(false);
    }
  }, [draft]);

  // Delete draft
  const discard = useCallback(async () => {
    if (!draft) return;

    try {
      setIsSaving(true);
      setSaveError(null);

      const success = await deleteItemDraft(draft.id);

      if (success) {
        setDraft(null);
        pendingUpdatesRef.current = null;
      } else {
        setSaveError('Failed to delete draft');
      }
    } catch (error: any) {
      setSaveError(error.message || 'Failed to delete draft');
    } finally {
      setIsSaving(false);
    }
  }, [draft]);

  // Setup autosave timer
  useEffect(() => {
    if (!draft) return;

    // Clear existing timer
    if (autosaveTimerRef.current) {
      clearInterval(autosaveTimerRef.current);
    }

    // Start new timer
    autosaveTimerRef.current = setInterval(() => {
      if (pendingUpdatesRef.current) {
        saveNow();
      }
    }, AUTOSAVE_INTERVAL_MS);

    return () => {
      if (autosaveTimerRef.current) {
        clearInterval(autosaveTimerRef.current);
      }
    };
  }, [draft, saveNow]);

  // Flush on AppState change to background
  useEffect(() => {
    const subscription = AppState.addEventListener('change', (nextAppState: AppStateStatus) => {
      if (
        appStateRef.current.match(/active|inactive/) &&
        nextAppState === 'background'
      ) {
        // App going to background - flush pending updates
        if (pendingUpdatesRef.current) {
          saveNow();
        }
      }
      appStateRef.current = nextAppState;
    });

    return () => {
      subscription.remove();
    };
  }, [saveNow]);

  // Flush on navigation blur (screen loses focus)
  useFocusEffect(
    useCallback(() => {
      return () => {
        // Screen is blurring - flush pending updates
        if (pendingUpdatesRef.current) {
          saveNow();
        }
      };
    }, [saveNow])
  );

  return {
    draft,
    save,
    saveNow,
    discard,
    isSaving,
    saveError,
    isLoading,
  };
}

/**
 * File: p2p-kids-marketplace/src/hooks/useAIAnalysis.ts
 * MODULE-04 LISTING-V3-004: AI Analysis Hook
 * 
 * Provides AI photo analysis with:
 * - Automatic analysis trigger on photo URLs change
 * - AbortController cancellation on URL change
 * - Single retry on network error
 * - Status state management
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { AIAnalysisResult } from '../types/listing';
import { analyzePhotosBatch, BatchAnalysisItem } from '../services/aiService';

const RETRY_DELAY_MS = 1500;

export type AIAnalysisStatus = 'idle' | 'analyzing' | 'ready' | 'error';

export interface UseAIAnalysisResult {
  status: AIAnalysisStatus;
  result: AIAnalysisResult | null;
  error: string | null;
  retry: () => void;
}

/**
 * Hook for AI photo analysis
 * 
 * Features:
 * - Does NOT auto-run until photoUrls.length > 0
 * - Aborts pending fetch when photoUrls change
 * - Single retry on network error with 1.5s delay
 * - Returns status: idle | analyzing | ready | error
 * 
 * @param photoUrls - Array of photo URLs to analyze
 * @param sellerId - Seller ID for analysis request
 * @returns Analysis state and retry method
 */
export function useAIAnalysis(
  photoUrls: string[],
  sellerId: string
): UseAIAnalysisResult {
  const [status, setStatus] = useState<AIAnalysisStatus>('idle');
  const [result, setResult] = useState<AIAnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const abortControllerRef = useRef<AbortController | null>(null);
  const retryCountRef = useRef(0);
  const photoUrlsRef = useRef<string[]>([]);

  // Perform analysis
  const analyze = useCallback(async () => {
    if (photoUrls.length === 0) {
      setStatus('idle');
      setResult(null);
      setError(null);
      return;
    }

    // Abort previous request if still running
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    // Create new abort controller
    abortControllerRef.current = new AbortController();

    try {
      setStatus('analyzing');
      setError(null);

      // Build batch analysis request
      const items: BatchAnalysisItem[] = [
        {
          groupId: 'single-item',
          primaryPhotoUrl: photoUrls[0],
          allPhotoUrls: photoUrls,
        },
      ];

      // Call batch analysis service
      const response = await analyzePhotosBatch(items, sellerId);

      // Check if request was aborted
      if (abortControllerRef.current?.signal.aborted) {
        return;
      }

      // Extract result for single item
      const itemResult = response.results[0];

      if (itemResult?.error) {
        throw new Error(itemResult.error);
      }

      if (itemResult?.analysis) {
        setResult(itemResult.analysis);
        setStatus('ready');
        retryCountRef.current = 0;
      } else {
        throw new Error('No analysis result returned');
      }
    } catch (err: any) {
      // Check if request was aborted
      if (abortControllerRef.current?.signal.aborted) {
        return;
      }

      const errorMessage = err.message || 'Analysis failed';
      setError(errorMessage);
      setStatus('error');

      // Retry once on network error
      if (retryCountRef.current === 0 && errorMessage.toLowerCase().includes('network')) {
        retryCountRef.current++;
        setTimeout(() => {
          analyze();
        }, RETRY_DELAY_MS);
      }
    }
  }, [photoUrls, sellerId]);

  // Trigger analysis when photo URLs change
  useEffect(() => {
    const urlsChanged = JSON.stringify(photoUrls) !== JSON.stringify(photoUrlsRef.current);

    if (urlsChanged) {
      photoUrlsRef.current = photoUrls;
      retryCountRef.current = 0;
      analyze();
    }
  }, [photoUrls, analyze]);

  // Manual retry method
  const retry = useCallback(() => {
    retryCountRef.current = 0;
    analyze();
  }, [analyze]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, []);

  return {
    status,
    result,
    error,
    retry,
  };
}

/**
 * File: p2p-kids-marketplace/src/hooks/usePhotoGroups.ts
 * MODULE-04 LISTING-V3-004: Photo Groups Hook
 * 
 * Provides photo grouping state management for bulk listing with:
 * - Add/remove/reorder photos
 * - Regroup photos between items
 * - Set cover photo
 * - Cap enforcement (10/group, 30 total, 15 groups)
 * - Error state instead of throwing
 */

import { useState, useCallback } from 'react';
import { PhotoAsset, PhotoGroup } from '../types/listing';
import { v4 as uuidv4 } from 'uuid';

const MAX_PHOTOS_PER_GROUP = 10;
const MAX_PHOTOS_TOTAL = 30;
const MAX_GROUPS = 15;

export interface PhotoGroupError {
  type: 'max_photos_total' | 'max_photos_per_group' | 'max_groups' | 'invalid_operation';
  message: string;
}

export interface UsePhotoGroupsResult {
  groups: PhotoGroup[];
  addPhotos: (photos: PhotoAsset[]) => void;
  removePhoto: (groupId: string, photoId: string) => void;
  reorderPhotos: (groupId: string, fromIndex: number, toIndex: number) => void;
  regroup: (photoId: string, fromGroupId: string, toGroupId: string) => void;
  setCover: (groupId: string, photoIndex: number) => void;
  createGroup: () => void;
  removeGroup: (groupId: string) => void;
  errors: PhotoGroupError[];
  clearErrors: () => void;
  totalPhotos: number;
}

/**
 * Hook for managing photo groups in bulk listing
 * 
 * Features:
 * - Enforces caps: 10 photos/group, 30 total, 15 groups
 * - Returns errors array instead of throwing
 * - Immutable operations (returns new state)
 * - Preserves intra-group order on regroup
 * 
 * @param initialGroups - Optional initial groups state
 * @returns Photo groups state and control methods
 */
export function usePhotoGroups(
  initialGroups: PhotoGroup[] = []
): UsePhotoGroupsResult {
  const [groups, setGroups] = useState<PhotoGroup[]>(initialGroups);
  const [errors, setErrors] = useState<PhotoGroupError[]>([]);

  // Calculate total photos across all groups
  const totalPhotos = groups.reduce((sum, group) => sum + group.photos.length, 0);

  // Add error
  const addError = useCallback((error: PhotoGroupError) => {
    setErrors((prev) => [...prev, error]);
  }, []);

  // Clear all errors
  const clearErrors = useCallback(() => {
    setErrors([]);
  }, []);

  // Add photos to a new or existing group
  const addPhotos = useCallback((photos: PhotoAsset[]) => {
    clearErrors();

    // Check total photos cap
    if (totalPhotos + photos.length > MAX_PHOTOS_TOTAL) {
      addError({
        type: 'max_photos_total',
        message: `Cannot add ${photos.length} photos. Maximum ${MAX_PHOTOS_TOTAL} total photos allowed.`,
      });
      return;
    }

    // Create new group for photos or add to last group if space available
    setGroups((prev) => {
      const newGroups = [...prev];
      let remainingPhotos = [...photos];

      // Try to fill last group first
      if (newGroups.length > 0) {
        const lastGroup = newGroups[newGroups.length - 1];
        const availableSpace = MAX_PHOTOS_PER_GROUP - lastGroup.photos.length;

        if (availableSpace > 0) {
          const photosToAdd = remainingPhotos.splice(0, availableSpace);
          lastGroup.photos = [...lastGroup.photos, ...photosToAdd];
        }
      }

      // Create new groups for remaining photos
      while (remainingPhotos.length > 0) {
        if (newGroups.length >= MAX_GROUPS) {
          addError({
            type: 'max_groups',
            message: `Maximum ${MAX_GROUPS} groups allowed.`,
          });
          break;
        }

        const groupPhotos = remainingPhotos.splice(0, MAX_PHOTOS_PER_GROUP);
        newGroups.push({
          groupId: uuidv4(),
          photos: groupPhotos,
          primaryPhotoIndex: 0,
        });
      }

      return newGroups;
    });
  }, [totalPhotos, addError, clearErrors]);

  // Remove photo from a group
  const removePhoto = useCallback((groupId: string, photoId: string) => {
    clearErrors();

    setGroups((prev) => {
      const newGroups = prev.map((group) => {
        if (group.groupId !== groupId) return group;

        const photoIndex = group.photos.findIndex((p) => p.id === photoId);
        if (photoIndex === -1) return group;

        const newPhotos = group.photos.filter((p) => p.id !== photoId);

        // Adjust primary photo index if needed
        let newPrimaryIndex = group.primaryPhotoIndex;
        if (photoIndex === group.primaryPhotoIndex) {
          newPrimaryIndex = 0; // Reset to first photo
        } else if (photoIndex < group.primaryPhotoIndex) {
          newPrimaryIndex = group.primaryPhotoIndex - 1;
        }

        return {
          ...group,
          photos: newPhotos,
          primaryPhotoIndex: Math.min(newPrimaryIndex, newPhotos.length - 1),
        };
      });

      // Remove empty groups
      return newGroups.filter((g) => g.photos.length > 0);
    });
  }, [clearErrors]);

  // Reorder photos within a group
  const reorderPhotos = useCallback(
    (groupId: string, fromIndex: number, toIndex: number) => {
      clearErrors();

      setGroups((prev) => {
        return prev.map((group) => {
          if (group.groupId !== groupId) return group;

          const newPhotos = [...group.photos];
          const [movedPhoto] = newPhotos.splice(fromIndex, 1);
          newPhotos.splice(toIndex, 0, movedPhoto);

          // Adjust primary photo index if the primary photo was moved
          let newPrimaryIndex = group.primaryPhotoIndex;
          if (fromIndex === group.primaryPhotoIndex) {
            newPrimaryIndex = toIndex;
          } else if (fromIndex < group.primaryPhotoIndex && toIndex >= group.primaryPhotoIndex) {
            newPrimaryIndex = group.primaryPhotoIndex - 1;
          } else if (fromIndex > group.primaryPhotoIndex && toIndex <= group.primaryPhotoIndex) {
            newPrimaryIndex = group.primaryPhotoIndex + 1;
          }

          return {
            ...group,
            photos: newPhotos,
            primaryPhotoIndex: newPrimaryIndex,
          };
        });
      });
    },
    [clearErrors]
  );

  // Move photo from one group to another
  const regroup = useCallback(
    (photoId: string, fromGroupId: string, toGroupId: string) => {
      clearErrors();

      setGroups((prev) => {
        const fromGroup = prev.find((g) => g.groupId === fromGroupId);
        const toGroup = prev.find((g) => g.groupId === toGroupId);

        if (!fromGroup || !toGroup) {
          addError({
            type: 'invalid_operation',
            message: 'Invalid group IDs',
          });
          return prev;
        }

        // Check destination group capacity
        if (toGroup.photos.length >= MAX_PHOTOS_PER_GROUP) {
          addError({
            type: 'max_photos_per_group',
            message: `Group already has maximum ${MAX_PHOTOS_PER_GROUP} photos`,
          });
          return prev;
        }

        const photoIndex = fromGroup.photos.findIndex((p) => p.id === photoId);
        if (photoIndex === -1) {
          addError({
            type: 'invalid_operation',
            message: 'Photo not found in source group',
          });
          return prev;
        }

        return prev.map((group) => {
          if (group.groupId === fromGroupId) {
            // Remove photo from source group
            const newPhotos = group.photos.filter((p) => p.id !== photoId);
            let newPrimaryIndex = group.primaryPhotoIndex;

            if (photoIndex === group.primaryPhotoIndex) {
              newPrimaryIndex = 0;
            } else if (photoIndex < group.primaryPhotoIndex) {
              newPrimaryIndex = group.primaryPhotoIndex - 1;
            }

            return {
              ...group,
              photos: newPhotos,
              primaryPhotoIndex: Math.min(newPrimaryIndex, newPhotos.length - 1),
            };
          } else if (group.groupId === toGroupId) {
            // Add photo to destination group
            const photo = fromGroup.photos[photoIndex];
            return {
              ...group,
              photos: [...group.photos, photo],
            };
          }
          return group;
        }).filter((g) => g.photos.length > 0); // Remove empty groups
      });
    },
    [addError, clearErrors]
  );

  // Set cover photo for a group
  const setCover = useCallback(
    (groupId: string, photoIndex: number) => {
      clearErrors();

      setGroups((prev) => {
        return prev.map((group) => {
          if (group.groupId !== groupId) return group;

          if (photoIndex < 0 || photoIndex >= group.photos.length) {
            addError({
              type: 'invalid_operation',
              message: 'Invalid photo index',
            });
            return group;
          }

          return {
            ...group,
            primaryPhotoIndex: photoIndex,
          };
        });
      });
    },
    [addError, clearErrors]
  );

  // Create empty group
  const createGroup = useCallback(() => {
    clearErrors();

    if (groups.length >= MAX_GROUPS) {
      addError({
        type: 'max_groups',
        message: `Maximum ${MAX_GROUPS} groups allowed`,
      });
      return;
    }

    setGroups((prev) => [
      ...prev,
      {
        groupId: uuidv4(),
        photos: [],
        primaryPhotoIndex: 0,
      },
    ]);
  }, [groups.length, addError, clearErrors]);

  // Remove entire group
  const removeGroup = useCallback(
    (groupId: string) => {
      clearErrors();
      setGroups((prev) => prev.filter((g) => g.groupId !== groupId));
    },
    [clearErrors]
  );

  return {
    groups,
    addPhotos,
    removePhoto,
    reorderPhotos,
    regroup,
    setCover,
    createGroup,
    removeGroup,
    errors,
    clearErrors,
    totalPhotos,
  };
}

/**
 * File: p2p-kids-marketplace/src/hooks/useItemDraft.ts
 * MODULE-04 LISTING-V3-004: Item Draft Hook
 * 
 * Provides autosave functionality for item drafts with:
 * - 30-second interval auto-save
 * - AppState background flush
 * - Navigation blur flush
 * - Immediate save method
 * - Error state management
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { AppState, AppStateStatus } from 'react-native';
import { useNavigation, useFocusEffect } from '@react-navigation/native';
import { ItemDraft, DraftData } from '../types/listing';
import {
  createItemDraft,
  getItemDraft,
  updateItemDraft,
  deleteItemDraft,
} from '../services/draftService';

const AUTOSAVE_INTERVAL_MS = 30000; // 30 seconds

export interface UseItemDraftResult {
  draft: ItemDraft | null;
  save: (updates: Partial<DraftData>) => void;
  saveNow: () => Promise<void>;
  discard: () => Promise<void>;
  isSaving: boolean;
  saveError: string | null;
  isLoading: boolean;
}

/**
 * Hook for managing item draft with autosave
 * 
 * Features:
 * - Loads existing draft on mount if draftId provided
 * - Auto-saves every 30s while screen is focused
 * - Flushes pending changes on AppState -> background
 * - Flushes pending changes on navigation blur
 * - Provides immediate save method
 * - Never throws - exposes saveError instead
 * 
 * @param draftId - Optional existing draft ID to load
 * @param sellerId - Seller ID for creating new draft
 * @returns Draft state and control methods
 */
export function useItemDraft(
  draftId?: string,
  sellerId?: string
): UseItemDraftResult {
  const [draft, setDraft] = useState<ItemDraft | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const navigation = useNavigation();
  const autosaveTimerRef = useRef<NodeJS.Timeout | null>(null);
  const pendingUpdatesRef = useRef<Partial<DraftData> | null>(null);
  const appStateRef = useRef(AppState.currentState);

  // Load existing draft on mount
  useEffect(() => {
    if (draftId) {
      loadDraft(draftId);
    } else if (sellerId) {
      createNewDraft(sellerId);
    } else {
      setIsLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draftId, sellerId]);

  // Load draft from server
  const loadDraft = async (id: string) => {
    try {
      setIsLoading(true);
      const loaded = await getItemDraft(id);
      if (loaded) {
        setDraft(loaded);
      } else {
        setSaveError('Draft not found or expired');
      }
    } catch (error: any) {
      setSaveError(error.message || 'Failed to load draft');
    } finally {
      setIsLoading(false);
    }
  };

  // Create new draft
  const createNewDraft = async (seller_id: string) => {
    try {
      setIsLoading(true);
      const created = await createItemDraft(seller_id);
      if (created) {
        setDraft(created);
      } else {
        setSaveError('Failed to create draft');
      }
    } catch (error: any) {
      setSaveError(error.message || 'Failed to create draft');
    } finally {
      setIsLoading(false);
    }
  };

  // Queue updates for autosave
  const save = useCallback((updates: Partial<DraftData>) => {
    setSaveError(null);

    // Merge with pending updates
    if (pendingUpdatesRef.current) {
      pendingUpdatesRef.current = { ...pendingUpdatesRef.current, ...updates };
    } else {
      pendingUpdatesRef.current = updates;
    }

    // Update local draft state immediately for UI responsiveness
    setDraft((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        draft_data: { ...prev.draft_data, ...updates },
        updated_at: new Date().toISOString(),
      };
    });
  }, []);

  // Flush pending updates immediately
  const saveNow = useCallback(async () => {
    if (!draft || !pendingUpdatesRef.current) return;

    try {
      setIsSaving(true);
      setSaveError(null);

      const success = await updateItemDraft(draft.id, pendingUpdatesRef.current);

      if (success) {
        pendingUpdatesRef.current = null;
      } else {
        setSaveError('Failed to save draft');
      }
    } catch (error: any) {
      setSaveError(error.message || 'Failed to save draft');
    } finally {
      setIsSaving(false);
    }
  }, [draft]);

  // Delete draft
  const discard = useCallback(async () => {
    if (!draft) return;

    try {
      setIsSaving(true);
      setSaveError(null);

      const success = await deleteItemDraft(draft.id);

      if (success) {
        setDraft(null);
        pendingUpdatesRef.current = null;
      } else {
        setSaveError('Failed to delete draft');
      }
    } catch (error: any) {
      setSaveError(error.message || 'Failed to delete draft');
    } finally {
      setIsSaving(false);
    }
  }, [draft]);

  // Setup autosave timer
  useEffect(() => {
    if (!draft) return;

    // Clear existing timer
    if (autosaveTimerRef.current) {
      clearInterval(autosaveTimerRef.current);
    }

    // Start new timer
    autosaveTimerRef.current = setInterval(() => {
      if (pendingUpdatesRef.current) {
        saveNow();
      }
    }, AUTOSAVE_INTERVAL_MS);

    return () => {
      if (autosaveTimerRef.current) {
        clearInterval(autosaveTimerRef.current);
      }
    };
  }, [draft, saveNow]);

  // Flush on AppState change to background
  useEffect(() => {
    const subscription = AppState.addEventListener('change', (nextAppState: AppStateStatus) => {
      if (
        appStateRef.current.match(/active|inactive/) &&
        nextAppState === 'background'
      ) {
        // App going to background - flush pending updates
        if (pendingUpdatesRef.current) {
          saveNow();
        }
      }
      appStateRef.current = nextAppState;
    });

    return () => {
      subscription.remove();
    };
  }, [saveNow]);

  // Flush on navigation blur (screen loses focus)
  useFocusEffect(
    useCallback(() => {
      return () => {
        // Screen is blurring - flush pending updates
        if (pendingUpdatesRef.current) {
          saveNow();
        }
      };
    }, [saveNow])
  );

  return {
    draft,
    save,
    saveNow,
    discard,
    isSaving,
    saveError,
    isLoading,
  };
}

/**
 * File: p2p-kids-marketplace/src/hooks/useAIAnalysis.ts
 * MODULE-04 LISTING-V3-004: AI Analysis Hook
 * 
 * Provides AI photo analysis with:
 * - Automatic analysis trigger on photo URLs change
 * - AbortController cancellation on URL change
 * - Single retry on network error
 * - Status state management
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { AIAnalysisResult } from '../types/listing';
import { analyzePhotosBatch, BatchAnalysisItem } from '../services/aiService';

const RETRY_DELAY_MS = 1500;

export type AIAnalysisStatus = 'idle' | 'analyzing' | 'ready' | 'error';

export interface UseAIAnalysisResult {
  status: AIAnalysisStatus;
  result: AIAnalysisResult | null;
  error: string | null;
  retry: () => void;
}

/**
 * Hook for AI photo analysis
 * 
 * Features:
 * - Does NOT auto-run until photoUrls.length > 0
 * - Aborts pending fetch when photoUrls change
 * - Single retry on network error with 1.5s delay
 * - Returns status: idle | analyzing | ready | error
 * 
 * @param photoUrls - Array of photo URLs to analyze
 * @param sellerId - Seller ID for analysis request
 * @returns Analysis state and retry method
 */
export function useAIAnalysis(
  photoUrls: string[],
  sellerId: string
): UseAIAnalysisResult {
  const [status, setStatus] = useState<AIAnalysisStatus>('idle');
  const [result, setResult] = useState<AIAnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const abortControllerRef = useRef<AbortController | null>(null);
  const retryCountRef = useRef(0);
  const photoUrlsRef = useRef<string[]>([]);

  // Perform analysis
  const analyze = useCallback(async () => {
    if (photoUrls.length === 0) {
      setStatus('idle');
      setResult(null);
      setError(null);
      return;
    }

    // Abort previous request if still running
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    // Create new abort controller
    abortControllerRef.current = new AbortController();

    try {
      setStatus('analyzing');
      setError(null);

      // Build batch analysis request
      const items: BatchAnalysisItem[] = [
        {
          groupId: 'single-item',
          primaryPhotoUrl: photoUrls[0],
          allPhotoUrls: photoUrls,
        },
      ];

      // Call batch analysis service
      const response = await analyzePhotosBatch(items, sellerId);

      // Check if request was aborted
      if (abortControllerRef.current?.signal.aborted) {
        return;
      }

      // Extract result for single item
      const itemResult = response.results[0];

      if (itemResult?.error) {
        throw new Error(itemResult.error);
      }

      if (itemResult?.analysis) {
        setResult(itemResult.analysis);
        setStatus('ready');
        retryCountRef.current = 0;
      } else {
        throw new Error('No analysis result returned');
      }
    } catch (err: any) {
      // Check if request was aborted
      if (abortControllerRef.current?.signal.aborted) {
        return;
      }

      const errorMessage = err.message || 'Analysis failed';
      setError(errorMessage);
      setStatus('error');

      // Retry once on network error
      if (retryCountRef.current === 0 && errorMessage.toLowerCase().includes('network')) {
        retryCountRef.current++;
        setTimeout(() => {
          analyze();
        }, RETRY_DELAY_MS);
      }
    }
  }, [photoUrls, sellerId]);

  // Trigger analysis when photo URLs change
  useEffect(() => {
    const urlsChanged = JSON.stringify(photoUrls) !== JSON.stringify(photoUrlsRef.current);

    if (urlsChanged) {
      photoUrlsRef.current = photoUrls;
      retryCountRef.current = 0;
      analyze();
    }
  }, [photoUrls, analyze]);

  // Manual retry method
  const retry = useCallback(() => {
    retryCountRef.current = 0;
    analyze();
  }, [analyze]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, []);

  return {
    status,
    result,
    error,
    retry,
  };
}

/**
 * File: p2p-kids-marketplace/src/hooks/usePhotoGroups.ts
 * MODULE-04 LISTING-V3-004: Photo Groups Hook
 * 
 * Provides photo grouping state management for bulk listing with:
 * - Add/remove/reorder photos
 * - Regroup photos between items
 * - Set cover photo
 * - Cap enforcement (10/group, 30 total, 15 groups)
 * - Error state instead of throwing
 */

import { useState, useCallback } from 'react';
import { PhotoAsset, PhotoGroup } from '../types/listing';
import { v4 as uuidv4 } from 'uuid';

const MAX_PHOTOS_PER_GROUP = 10;
const MAX_PHOTOS_TOTAL = 30;
const MAX_GROUPS = 15;

export interface PhotoGroupError {
  type: 'max_photos_total' | 'max_photos_per_group' | 'max_groups' | 'invalid_operation';
  message: string;
}

export interface UsePhotoGroupsResult {
  groups: PhotoGroup[];
  addPhotos: (photos: PhotoAsset[]) => void;
  removePhoto: (groupId: string, photoId: string) => void;
  reorderPhotos: (groupId: string, fromIndex: number, toIndex: number) => void;
  regroup: (photoId: string, fromGroupId: string, toGroupId: string) => void;
  setCover: (groupId: string, photoIndex: number) => void;
  createGroup: () => void;
  removeGroup: (groupId: string) => void;
  errors: PhotoGroupError[];
  clearErrors: () => void;
  totalPhotos: number;
}

/**
 * Hook for managing photo groups in bulk listing
 * 
 * Features:
 * - Enforces caps: 10 photos/group, 30 total, 15 groups
 * - Returns errors array instead of throwing
 * - Immutable operations (returns new state)
 * - Preserves intra-group order on regroup
 * 
 * @param initialGroups - Optional initial groups state
 * @returns Photo groups state and control methods
 */
export function usePhotoGroups(
  initialGroups: PhotoGroup[] = []
): UsePhotoGroupsResult {
  const [groups, setGroups] = useState<PhotoGroup[]>(initialGroups);
  const [errors, setErrors] = useState<PhotoGroupError[]>([]);

  // Calculate total photos across all groups
  const totalPhotos = groups.reduce((sum, group) => sum + group.photos.length, 0);

  // Add error
  const addError = useCallback((error: PhotoGroupError) => {
    setErrors((prev) => [...prev, error]);
  }, []);

  // Clear all errors
  const clearErrors = useCallback(() => {
    setErrors([]);
  }, []);

  // Add photos to a new or existing group
  const addPhotos = useCallback((photos: PhotoAsset[]) => {
    clearErrors();

    // Check total photos cap
    if (totalPhotos + photos.length > MAX_PHOTOS_TOTAL) {
      addError({
        type: 'max_photos_total',
        message: `Cannot add ${photos.length} photos. Maximum ${MAX_PHOTOS_TOTAL} total photos allowed.`,
      });
      return;
    }

    // Create new group for photos or add to last group if space available
    setGroups((prev) => {
      const newGroups = [...prev];
      let remainingPhotos = [...photos];

      // Try to fill last group first
      if (newGroups.length > 0) {
        const lastGroup = newGroups[newGroups.length - 1];
        const availableSpace = MAX_PHOTOS_PER_GROUP - lastGroup.photos.length;

        if (availableSpace > 0) {
          const photosToAdd = remainingPhotos.splice(0, availableSpace);
          lastGroup.photos = [...lastGroup.photos, ...photosToAdd];
        }
      }

      // Create new groups for remaining photos
      while (remainingPhotos.length > 0) {
        if (newGroups.length >= MAX_GROUPS) {
          addError({
            type: 'max_groups',
            message: `Maximum ${MAX_GROUPS} groups allowed.`,
          });
          break;
        }

        const groupPhotos = remainingPhotos.splice(0, MAX_PHOTOS_PER_GROUP);
        newGroups.push({
          groupId: uuidv4(),
          photos: groupPhotos,
          primaryPhotoIndex: 0,
        });
      }

      return newGroups;
    });
  }, [totalPhotos, addError, clearErrors]);

  // Remove photo from a group
  const removePhoto = useCallback((groupId: string, photoId: string) => {
    clearErrors();

    setGroups((prev) => {
      const newGroups = prev.map((group) => {
        if (group.groupId !== groupId) return group;

        const photoIndex = group.photos.findIndex((p) => p.id === photoId);
        if (photoIndex === -1) return group;

        const newPhotos = group.photos.filter((p) => p.id !== photoId);

        // Adjust primary photo index if needed
        let newPrimaryIndex = group.primaryPhotoIndex;
        if (photoIndex === group.primaryPhotoIndex) {
          newPrimaryIndex = 0; // Reset to first photo
        } else if (photoIndex < group.primaryPhotoIndex) {
          newPrimaryIndex = group.primaryPhotoIndex - 1;
        }

        return {
          ...group,
          photos: newPhotos,
          primaryPhotoIndex: Math.min(newPrimaryIndex, newPhotos.length - 1),
        };
      });

      // Remove empty groups
      return newGroups.filter((g) => g.photos.length > 0);
    });
  }, [clearErrors]);

  // Reorder photos within a group
  const reorderPhotos = useCallback(
    (groupId: string, fromIndex: number, toIndex: number) => {
      clearErrors();

      setGroups((prev) => {
        return prev.map((group) => {
          if (group.groupId !== groupId) return group;

          const newPhotos = [...group.photos];
          const [movedPhoto] = newPhotos.splice(fromIndex, 1);
          newPhotos.splice(toIndex, 0, movedPhoto);

          // Adjust primary photo index if the primary photo was moved
          let newPrimaryIndex = group.primaryPhotoIndex;
          if (fromIndex === group.primaryPhotoIndex) {
            newPrimaryIndex = toIndex;
          } else if (fromIndex < group.primaryPhotoIndex && toIndex >= group.primaryPhotoIndex) {
            newPrimaryIndex = group.primaryPhotoIndex - 1;
          } else if (fromIndex > group.primaryPhotoIndex && toIndex <= group.primaryPhotoIndex) {
            newPrimaryIndex = group.primaryPhotoIndex + 1;
          }

          return {
            ...group,
            photos: newPhotos,
            primaryPhotoIndex: newPrimaryIndex,
          };
        });
      });
    },
    [clearErrors]
  );

  // Move photo from one group to another
  const regroup = useCallback(
    (photoId: string, fromGroupId: string, toGroupId: string) => {
      clearErrors();

      setGroups((prev) => {
        const fromGroup = prev.find((g) => g.groupId === fromGroupId);
        const toGroup = prev.find((g) => g.groupId === toGroupId);

        if (!fromGroup || !toGroup) {
          addError({
            type: 'invalid_operation',
            message: 'Invalid group IDs',
          });
          return prev;
        }

        // Check destination group capacity
        if (toGroup.photos.length >= MAX_PHOTOS_PER_GROUP) {
          addError({
            type: 'max_photos_per_group',
            message: `Group already has maximum ${MAX_PHOTOS_PER_GROUP} photos`,
          });
          return prev;
        }

        const photoIndex = fromGroup.photos.findIndex((p) => p.id === photoId);
        if (photoIndex === -1) {
          addError({
            type: 'invalid_operation',
            message: 'Photo not found in source group',
          });
          return prev;
        }

        return prev.map((group) => {
          if (group.groupId === fromGroupId) {
            // Remove photo from source group
            const newPhotos = group.photos.filter((p) => p.id !== photoId);
            let newPrimaryIndex = group.primaryPhotoIndex;

            if (photoIndex === group.primaryPhotoIndex) {
              newPrimaryIndex = 0;
            } else if (photoIndex < group.primaryPhotoIndex) {
              newPrimaryIndex = group.primaryPhotoIndex - 1;
            }

            return {
              ...group,
              photos: newPhotos,
              primaryPhotoIndex: Math.min(newPrimaryIndex, newPhotos.length - 1),
            };
          } else if (group.groupId === toGroupId) {
            // Add photo to destination group
            const photo = fromGroup.photos[photoIndex];
            return {
              ...group,
              photos: [...group.photos, photo],
            };
          }
          return group;
        }).filter((g) => g.photos.length > 0); // Remove empty groups
      });
    },
    [addError, clearErrors]
  );

  // Set cover photo for a group
  const setCover = useCallback(
    (groupId: string, photoIndex: number) => {
      clearErrors();

      setGroups((prev) => {
        return prev.map((group) => {
          if (group.groupId !== groupId) return group;

          if (photoIndex < 0 || photoIndex >= group.photos.length) {
            addError({
              type: 'invalid_operation',
              message: 'Invalid photo index',
            });
            return group;
          }

          return {
            ...group,
            primaryPhotoIndex: photoIndex,
          };
        });
      });
    },
    [addError, clearErrors]
  );

  // Create empty group
  const createGroup = useCallback(() => {
    clearErrors();

    if (groups.length >= MAX_GROUPS) {
      addError({
        type: 'max_groups',
        message: `Maximum ${MAX_GROUPS} groups allowed`,
      });
      return;
    }

    setGroups((prev) => [
      ...prev,
      {
        groupId: uuidv4(),
        photos: [],
        primaryPhotoIndex: 0,
      },
    ]);
  }, [groups.length, addError, clearErrors]);

  // Remove entire group
  const removeGroup = useCallback(
    (groupId: string) => {
      clearErrors();
      setGroups((prev) => prev.filter((g) => g.groupId !== groupId));
    },
    [clearErrors]
  );

  return {
    groups,
    addPhotos,
    removePhoto,
    reorderPhotos,
    regroup,
    setCover,
    createGroup,
    removeGroup,
    errors,
    clearErrors,
    totalPhotos,
  };
}

