        .mockRejectedValueOnce(new Error('Network error'))
        .mockResolvedValueOnce({
          results: [
            {
              groupId: 'single-item',
              analysis: mockAnalysisResult,
            },
          ],
          totalProcessed: 1,
          totalFailed: 0,
        });

      const { result } = renderHook(() =>
        useAIAnalysis(['https://example.com/photo1.jpg'], 'seller-123')
      );

