        result.current.save({ title: 'Updated title' });
      });

      await act(async () => {
        await result.current.saveNow();
      });

      expect(draftService.updateItemDraft).toHaveBeenCalledWith('draft-123', {
        description: 'First update',
        price: 30,
        title: 'Updated title',
      });
    });
  });
